function deleteString(s) {
  const n = s.length;
  const codes = Array.from(s, ch => ch.charCodeAt(0));
  const dp = new Array(n + 1).fill(0);
  let lcp = new Int32Array(n + 1);
  let lcpNext = new Int32Array(n + 1);

  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j > i; j--) {
      lcp[j] = codes[i] === codes[j] ? lcpNext[j + 1] + 1 : 0;
    }
    dp[i] = 1;
    for (let len = 1; i + 2 * len <= n; len++) {
      if (lcp[i + len] >= len) {
        dp[i] = Math.max(dp[i], dp[i + len] + 1);
      }
    }
    [lcp, lcpNext] = [lcpNext, lcp];
  }
  return dp[0];
}

