function deleteString(s) {
  // Try every legal deletion on the actual remaining string, memoised by that string.
  const memo = new Map();
  const most = rest => {
    if (memo.has(rest)) return memo.get(rest);
    let result = 1;
    for (let i = 1; 2 * i <= rest.length; i++) {
      if (rest.slice(0, i) === rest.slice(i, 2 * i)) result = Math.max(result, 1 + most(rest.slice(i)));
    }
    memo.set(rest, result);
    return result;
  };
  return most(s);
}

