function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = letters.slice(0, 1 + pick(size === 'large' ? 4 : 3));
  const n = size === 'large' ? 1600 + pick(401) : 1 + pick(10);
  const shape = pick(4);
  let s = '';
  if (shape === 0) {
    // Random letters from a small alphabet.
    while (s.length < n) s += alphabet[pick(alphabet.length)];
  } else if (shape === 1) {
    // A short block repeated, with a few letters changed so some repeats break.
    let block = '';
    const width = 1 + pick(size === 'large' ? 6 : 3);
    while (block.length < width) block += alphabet[pick(alphabet.length)];
    while (s.length < n) s += block;
    const chars = s.slice(0, n).split('');
    const changes = pick(size === 'large' ? 8 : 2);
    for (let c = 0; c < changes; c++) chars[pick(n)] = letters[pick(26)];
    s = chars.join('');
  } else if (shape === 2) {
    // Runs of one letter, so many short deletions are possible.
    while (s.length < n) s += alphabet[pick(alphabet.length)].repeat(1 + pick(size === 'large' ? 40 : 4));
  } else {
    // Fully random lowercase letters.
    while (s.length < n) s += letters[pick(26)];
  }
  return [s.slice(0, n)];
}
